	{
		f32 dot = step.x * away.x + step.y * away.y + step.z * away.z;
		step.Scale(AVOID_BUFFER, &step);

		if (dot < 0.0f)
		{
			step.x = -step.x;
			step.y = -step.y;
			step.z = -step.z;
		}
	}

	CPnt3D goal;
	body->GetPosW()->Add(&step, &goal);
	ai->SetGoalPos((GOAL_TYPE)5, &goal, 0.5f);
	ai->SetAiMode((AI_MODE)4);
