	if (m_critical)
	{
		ctrl->Debug("IN CRITICAL SECTION (anim:%s) -- can't switch sequences\n", name);
		return true;
	}

	const char* from = sealai::get_aiseq(old);
	const char* to = sealai::get_aiseq(aware);

